import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, length, uniform, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry, Color, DirectionalLight, AmbientLight, DoubleSide } = ctx.THREE;

  const COL = {
    bg: '#0b0b10',
    mid: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#14141a',
  };

  const root = new Group();
  root.name = 'orrery-mechanism';

  const primHandles = [];
  const timelines = [];
  const disposables = [];

  // ---- Backdrop plane with vertical/radial gradient ----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const c0 = uniform(new Color(COL.bg));
    const c1 = uniform(new Color(COL.mid));
    const c2 = uniform(new Color(COL.ink));
    const uvN = uv();
    // radial factor from center
    const d = length(uvN.sub(vec3(0.5, 0.5, 0.0).xy)).mul(1.4);
    // vertical gradient bottom->top mapped to stops
    const g1 = smoothstep(0.0, 0.65, uvN.y);
    const g2 = smoothstep(0.65, 1.0, uvN.y);
    const base = mix(c0, c1, g1);
    const grad = mix(base, c2, g2);
    // subtle radial darkening at edges
    const vig = smoothstep(1.1, 0.2, d);
    backdropMat.colorNode = mix(c0, grad, vig.mul(0.9).add(0.1));
    backdropMat.fog = false;
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- Fog for depth ----
  // Applied to a local group won't propagate to scene fog; skip global fog mutation.

  // ---- Lighting (node-local rim + ambient fill) ----
  const ambient = new AmbientLight(new Color('#20202a'), 0.5);
  root.add(ambient);

  const rim = new DirectionalLight(new Color(COL.accent), 1.2);
  rim.position.set(-3, 2, -2);
  root.add(rim);

  const key = new DirectionalLight(new Color('#cfd6e2'), 1.1);
  key.position.set(3, 3, 4);
  root.add(key);

  // ---- Machined steel material for gears ----
  function makeSteel() {
    const m = new MeshPhysicalNodeMaterial();
    m.color = new Color('#8a8f98');
    m.roughness = 0.5;
    m.metalness = 0.55;
    m.clearcoat = 0.2;
    m.clearcoatRoughness = 0.3;
    disposables.push(m);
    return m;
  }

  // ---- Gear group (mesh loaded async) ----
  const gearGroup = new Group();
  root.add(gearGroup);

  const primaryPivot = new Group();
  const secondaryPivot = new Group();
  secondaryPivot.position.set(1.15, 0.35, -0.1);
  gearGroup.add(primaryPivot);
  gearGroup.add(secondaryPivot);

  function normalizeAndAdd(gltf, pivot, targetDiameter) {
    const src = gltf.scene;
    // compute bounding box
    const box = new ctx.THREE.Box3().setFromObject(src);
    const size = new ctx.THREE.Vector3();
    box.getSize(size);
    const maxDim = Math.max(size.x, size.y) || 1;
    const s = targetDiameter / maxDim;
    src.scale.setScalar(s);
    const center = new ctx.THREE.Vector3();
    box.getCenter(center);
    src.position.sub(center.multiplyScalar(s));
    const steel = makeSteel();
    src.traverse((o) => {
      if (o.isMesh) {
        o.material = steel;
      }
    });
    pivot.add(src);
  }

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      normalizeAndAdd(gltf, primaryPivot, 1.6);
    }).catch(() => {});
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      normalizeAndAdd(gltf, secondaryPivot, 0.9);
    }).catch(() => {});
  }

  // ---- Jewel pivot sphere at primary hub ----
  const jewelGeo = new SphereGeometry(0.12, 32, 24);
  const jewelMat = new MeshPhysicalNodeMaterial();
  jewelMat.color = new Color(COL.accent);
  jewelMat.transmission = 0.6;
  jewelMat.ior = 1.76;
  jewelMat.thickness = 0.2;
  jewelMat.roughness = 0.15;
  jewelMat.metalness = 0.0;
  jewelMat.emissive = new Color(COL.accent);
  jewelMat.emissiveIntensity = 1.8;
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.05);
  primaryPivot.add(jewel);
  disposables.push(jewelGeo, jewelMat);

  // ---- Arbor shafts ----
  const arborMat = makeSteel();
  arborMat.color = new Color(COL.ink);
  arborMat.metalness = 0.5;
  arborMat.roughness = 0.6;
  const arborGeoA = new CylinderGeometry(0.05, 0.05, 0.8, 20);
  const arborA = new Mesh(arborGeoA, arborMat);
  arborA.rotation.x = Math.PI / 2;
  primaryPivot.add(arborA);
  const arborGeoB = new CylinderGeometry(0.05, 0.05, 0.8, 20);
  const arborB = new Mesh(arborGeoB, arborMat);
  arborB.rotation.x = Math.PI / 2;
  secondaryPivot.add(arborB);
  disposables.push(arborGeoA, arborGeoB);

  // ---- Contact shadow ellipse ----
  const shadowGeo = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  {
    const uvN = uv();
    const d = length(uvN.sub(vec3(0.5, 0.5, 0.0).xy)).mul(2.0);
    const a = smoothstep(1.0, 0.0, d).mul(0.5);
    shadowMat.colorNode = vec4(0.0, 0.0, 0.0, 1.0);
    shadowMat.opacityNode = a;
  }
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.2, 0);
  root.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---- Text ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  root.add(textGroup);

  let headlineText = 'The going train';
  let captionText = '34 COMPONENTS / HAND-FINISHED';
  for (const item of items) {
    if (item.role === 'headline' && item.text) headlineText = item.text;
    if (item.role === 'caption' && item.text) captionText = item.text;
  }

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: COL.paper,
    align: 'center',
  });
  headline.position.set(0, -1.7, 0.2);
  textGroup.add(headline);

  const caption = ctx.fontAtlas.createText(captionText, {
    fontSize: 18,
    color: COL.accent,
    align: 'center',
    letterSpacingPx: 2,
  });
  caption.position.set(0, -2.1, 0.2);
  textGroup.add(caption);

  // ---- Meshing rotation (phase-locked) ----
  const tl = gsap.timeline({ repeat: -1 });
  timelines.push(tl);
  const rot = { p: 0, s: 0 };
  const rotTl = gsap.to(rot, {
    p: Math.PI * 2,
    s: -Math.PI * 2 * (16 / 9),
    duration: (Math.PI * 2) / 0.08,
    ease: 'none',
    repeat: -1,
    onUpdate: () => {
      primaryPivot.rotation.z = rot.p;
      secondaryPivot.rotation.z = rot.s;
    },
  });
  timelines.push(rotTl);

  // ---- Entrance ----
  gearGroup.scale.setScalar(0.9);
  const entrance = gsap.to(gearGroup.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entrance);

  textGroup.position.y = 0.2;
  const textEntrance = gsap.from(textGroup.position, {
    y: -0.2,
    duration: 0.7,
    ease: 'power3.out',
  });
  timelines.push(textEntrance);

  // ---- Apply cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (fn) {
      const handle = fn(root, p.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t && t.kill());
    primHandles.forEach((h) => h && h.cleanup && h.cleanup());
    disposables.forEach((d) => d && d.dispose && d.dispose());
    root.traverse((o) => {
      if (o.isMesh) {
        o.geometry && o.geometry.dispose && o.geometry.dispose();
        if (o.material) {
          if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose && m.dispose());
          else o.material.dispose && o.material.dispose();
        }
      }
    });
  };

  return root;
}
